import{_ as t,o as a,c as i,ag as s}from"./chunks/framework.D9ghT4bC.js";const f=JSON.parse('{"title":"Mod file structure Overview","description":"","frontmatter":{},"headers":[],"relativePath":"Modders/Mod-file-structure/1-Overview.md","filePath":"Modders/Mod-file-structure/1-Overview.md"}'),n={name:"Modders/Mod-file-structure/1-Overview.md"};function o(l,e,r,d,u,h){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="mod-file-structure-overview" tabindex="-1">Mod file structure Overview <a class="header-anchor" href="#mod-file-structure-overview" aria-label="Permalink to &quot;Mod file structure Overview&quot;">​</a></h1><p>These pages are a work in progress. Information they contain may be incomplete.</p><p>The JSON files that make up mods can have many different fields, and as not all are used in the base game, this wiki page will contain the full information of each. It will also give a short explanation of the syntax of JSON files.</p><h2 id="table-of-contents" tabindex="-1">Table of Contents <a class="header-anchor" href="#table-of-contents" aria-label="Permalink to &quot;Table of Contents&quot;">​</a></h2><ul><li><a href="#general-overview-of-json-files">General Overview of JSON files</a></li><li><a href="./2-Civilization-related-JSON-files.html">Civilization-related JSON files</a><ul><li><a href="./2-Civilization-related-JSON-files.html#beliefs-json">Beliefs.json</a></li><li><a href="./2-Civilization-related-JSON-files.html#buildings-json">Buildings.json</a></li><li><a href="./2-Civilization-related-JSON-files.html#citystatetypes-json">CityStateTypes.json</a></li><li><a href="./2-Civilization-related-JSON-files.html#nations-json">Nations.json</a></li><li><a href="./2-Civilization-related-JSON-files.html#policies-json">Policies.json</a></li><li><a href="./2-Civilization-related-JSON-files.html#quests-json">Quests.json</a></li><li><a href="./2-Civilization-related-JSON-files.html#religions-json">Religions.json</a></li><li><a href="./2-Civilization-related-JSON-files.html#specialists-json">Specialists.json</a></li><li><a href="./2-Civilization-related-JSON-files.html#techs-json">Techs.json</a></li></ul></li><li><a href="./3-Map-related-JSON-files.html">Map-related JSON files</a><ul><li><a href="./3-Map-related-JSON-files.html#terrains-json">Terrains.json</a></li><li><a href="./3-Map-related-JSON-files.html#tileresources-json">TileResources.json</a></li><li><a href="./3-Map-related-JSON-files.html#tileimprovements-json">TileImprovements.json</a></li><li><a href="./3-Map-related-JSON-files.html#ruins-json">Ruins.json</a></li><li><a href="./3-Map-related-JSON-files.html#tileset-specific-json">Tileset-specific json</a></li></ul></li><li><a href="./4-Unit-related-JSON-files.html">Unit-related JSON files</a><ul><li><a href="./4-Unit-related-JSON-files.html#units-json">Units.json</a></li><li><a href="./4-Unit-related-JSON-files.html#unitpromotions-json">UnitPromotions.json</a></li><li><a href="./4-Unit-related-JSON-files.html#unittypes-json">UnitTypes.json</a></li><li><a href="./4-Unit-related-JSON-files.html#unitnamegroups-json">UnitNameGroups.json</a></li></ul></li><li><a href="./5-Miscellaneous-JSON-files.html">Miscellaneous JSON files</a><ul><li><a href="./5-Miscellaneous-JSON-files.html#difficulties-json">Difficulties.json</a></li><li><a href="./5-Miscellaneous-JSON-files.html#eras-json">Eras.json</a></li><li><a href="./5-Miscellaneous-JSON-files.html#modoptions-json">ModOptions.json</a></li><li><a href="./5-Miscellaneous-JSON-files.html#globaluniques-json">GlobalUniques.json</a></li><li><a href="./5-Miscellaneous-JSON-files.html#speeds-json">Speeds.json</a></li><li><a href="./5-Miscellaneous-JSON-files.html#tutorials-json">Tutorials.json</a></li><li><a href="./5-Miscellaneous-JSON-files.html#victorytypes-json">VictoryTypes.json</a></li></ul></li><li><a href="./6-MergeActions.html">Merge Actions</a><ul><li><a href="./6-MergeActions.html#operation-types">Operation Types</a></li><li><a href="./6-MergeActions.html#conditions">Conditions</a></li><li><a href="./6-MergeActions.html#condition-reference">Condition Reference</a></li></ul></li><li><a href="./3-Map-related-JSON-files.html#stats">Stats</a></li><li><a href="./../Images-and-Audio.html#sounds">Sounds</a></li><li><a href="./5-Miscellaneous-JSON-files.html#civilopedia-text">Civilopedia text</a></li></ul><h2 id="general-overview-of-json-files" tabindex="-1">General Overview of JSON files <a class="header-anchor" href="#general-overview-of-json-files" aria-label="Permalink to &quot;General Overview of JSON files&quot;">​</a></h2><p><strong>Recommended reading</strong>: <a href="https://www.json.org/" target="_blank" rel="noreferrer">json.org</a>, <a href="https://standards.iso.org/ittf/PubliclyAvailableStandards/c071616_ISO_IEC_21778_2017.zip" target="_blank" rel="noreferrer">ISO standard</a></p><p>Almost all Unciv JSON files start with a &quot;[&quot; and end with a &quot;]&quot;. In between these are different objects of the type you are describing, each of which is contained between a &quot;{&quot; and a &quot;}&quot;. For example, a very simple units.json may look like:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;name&quot;: &quot;Warrior&quot;,</span></span>
<span class="line"><span>        &quot;cost&quot;: 16</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;name&quot;: &quot;Spearman&quot;,</span></span>
<span class="line"><span>        &quot;cost&quot;: 24,</span></span>
<span class="line"><span>        &quot;promotions&quot;: [&quot;Shock I&quot;, &quot;Drill I&quot;]</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>]</span></span></code></pre></div><p>This file contains two unit objects, one for a warrior and one for a spearman. These objects have different attributes, in this case &quot;name&quot;, &quot;cost&quot; and &quot;promotions&quot;. All these attributes have a certain type, a String (text) for &quot;name&quot;, an Integer for &quot;cost&quot; and a List of Strings for &quot;promotions&quot;.</p><p>There are different types of attributes:</p><table tabindex="0"><thead><tr><th>type</th><th>notes</th></tr></thead><tbody><tr><td>String</td><td>A word or sentence. Should be between double quotes (&quot;) and escape double quotes meant to be part of the text: <code>\\&quot;</code></td></tr><tr><td>Integer</td><td>A number. Can be both positive or negative. Should <strong>not</strong> be between quotes</td></tr><tr><td>Float</td><td>A number that can have decimal places. Remember to use <code>.</code> as the Json standard needs, not your local culture&#39;s decimal symbol. Scientific notation would work, though</td></tr><tr><td>Boolean</td><td>A value that can either be &#39;true&#39; or &#39;false&#39;. Should <strong>not</strong> be between quotes</td></tr><tr><td>List of [type]</td><td>If multiple values could apply (such as with the promotions above), they should be put inside a list. Each element of the list should be written like a normal attribute, separated by commas, and enclosed between square braces. E.g.: [&quot;Shock I&quot;, &quot;Shock II&quot;] or [1, 2, 3].</td></tr><tr><td>Object</td><td>The most complicated type of attribute. An object is comprised of multiple attributes, each of which again has a type. These attributes have a key (the part before the &quot;😊 and a value (the part behind it). For an example, see below.</td></tr></tbody></table><p>Example of a Buildings.json adding a new &quot;Cultural Library&quot; building which gives +50% science and +50% culture:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;name&quot;: &quot;Cultural Library&quot;</span></span>
<span class="line"><span>        &quot;percentStatBonus&quot; : {&quot;science&quot;: 50, &quot;culture&quot;: 50}</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>]</span></span></code></pre></div><p>The keys in this example are &quot;science&quot; and &quot;culture&quot;, and both have the value &quot;50&quot;.</p><p>In some sense you can see from these types that JSON files themselves are actually a list of objects, each describing a single building, unit or something else.</p><h2 id="requirements-for-base-rulesets" tabindex="-1">Requirements for Base Rulesets <a class="header-anchor" href="#requirements-for-base-rulesets" aria-label="Permalink to &quot;Requirements for Base Rulesets&quot;">​</a></h2><p>Base ruleset mods must be &quot;complete&quot; by themselves, but that does not mean they must include all possible json files nor define content in all of them. Here&#39;s a breakdown (WIP, possibly inaccurate):</p><table tabindex="0"><thead><tr><th>File</th><th>Empty allowed?</th><th>Default/fallback</th></tr></thead><tbody><tr><td><a href="./2-Civilization-related-JSON-files.html#beliefs-json">Beliefs</a></td><td>yes</td><td>none</td></tr><tr><td><a href="./2-Civilization-related-JSON-files.html#buildings-json">Buildings</a></td><td>no</td><td>none</td></tr><tr><td><a href="./2-Civilization-related-JSON-files.html#citystatetypes-json">CityStateTypes</a></td><td>no</td><td>vanilla</td></tr><tr><td><a href="./5-Miscellaneous-JSON-files.html#difficulties-json">Difficulties</a></td><td>no</td><td>vanilla</td></tr><tr><td><a href="./5-Miscellaneous-JSON-files.html#eras-json">Eras</a></td><td>no</td><td>none</td></tr><tr><td><a href="./5-Miscellaneous-JSON-files.html#globaluniques-json">GlobalUniques</a></td><td>yes</td><td>vanilla</td></tr><tr><td><a href="./5-Miscellaneous-JSON-files.html#modoptions-json">ModOptions</a></td><td>yes</td><td>generated on download</td></tr><tr><td><a href="./2-Civilization-related-JSON-files.html#nations-json">Nations</a></td><td>no</td><td>none</td></tr><tr><td><a href="./2-Civilization-related-JSON-files.html#policies-json">Policies</a></td><td>yes</td><td>none</td></tr><tr><td><a href="./2-Civilization-related-JSON-files.html#quests-json">Quests</a></td><td>yes</td><td>none</td></tr><tr><td><a href="./2-Civilization-related-JSON-files.html#religions-json">Religions</a></td><td>yes</td><td>none</td></tr><tr><td><a href="./3-Map-related-JSON-files.html#ruins-json">Ruins</a></td><td>yes</td><td>vanilla</td></tr><tr><td><a href="./2-Civilization-related-JSON-files.html#specialists-json">Specialists</a></td><td>yes</td><td>none</td></tr><tr><td><a href="./5-Miscellaneous-JSON-files.html#speeds-json">Speeds</a></td><td>no</td><td>vanilla</td></tr><tr><td><a href="./2-Civilization-related-JSON-files.html#techs-json">Techs</a></td><td>yes</td><td>none</td></tr><tr><td><a href="./3-Map-related-JSON-files.html#terrains-json">Terrains</a></td><td>no</td><td>none</td></tr><tr><td><a href="./3-Map-related-JSON-files.html#tileimprovements-json">TileImprovements</a></td><td>yes</td><td>none</td></tr><tr><td><a href="./3-Map-related-JSON-files.html#tileresources-json">TileResources</a></td><td>yes</td><td>none</td></tr><tr><td><a href="./5-Miscellaneous-JSON-files.html#tutorials-json">Tutorials</a></td><td>yes</td><td>builtin always displayed</td></tr><tr><td><a href="./4-Unit-related-JSON-files.html#unitpromotions-json">UnitPromotions</a></td><td>yes</td><td>none</td></tr><tr><td><a href="./4-Unit-related-JSON-files.html#units-json">Units</a></td><td>no</td><td>none</td></tr><tr><td><a href="./4-Unit-related-JSON-files.html#unittypes-json">UnitTypes</a></td><td>no</td><td>vanilla</td></tr><tr><td><a href="./5-Miscellaneous-JSON-files.html#victorytypes-json">VictoryTypes</a></td><td>no</td><td>vanilla</td></tr></tbody></table><ul><li>Mod loading never fails due to missing files, they default to empty at first. Then the fallbacks mentioned above are applied for base rulesets only. Inconsistencies after that step would be reported by the Mod checker.</li><li>GlobalUniques has a fallback used when the file is missing. Therefore, a mod can intentionally define there are none by including one with empty content (<code>{}</code>).</li><li>Ruins has a fallback used when the file is missing. Therefore, a mod can intentionally define there are none by including one with empty content (<code>[]</code>).</li></ul><h2 id="uniques" tabindex="-1">Uniques <a class="header-anchor" href="#uniques" aria-label="Permalink to &quot;Uniques&quot;">​</a></h2><p>&quot;Uniques&quot; are a label used by Unciv for extensible and customizable effects. Nearly every &quot;ruleset object&quot; allows a set of them, as a List with the name &quot;uniques&quot;.</p><p>Every Unique follows a general structure: <code>Unique type defining name [placeholder] more name [another placeholder] &lt;condition or trigger&gt; &lt;condition or trigger&gt;...</code> The entire string, excluding all <code>&lt;&gt;</code>-delimited conditionals or triggers with their separating blanks, and excluding the placeholders but not their <code>[]</code> delimiters, are used to look up the Unique&#39;s implementation. The content of the optional <code>[placeholder]</code>s are implementation-dependant, they are parameters modifying the effect, and described in <a href="./../Unique-parameters.html">Unique parameters</a>. All <code>&lt;condition or trigger&gt;</code>s are optional (but if they are used the spaces separating them are mandatory), and each in turn follows the Unique structure rules for the part between the <code>&lt;&gt;</code> angled brackets, including possible placeholders, but not nested conditionals.</p><p>Example: <code>&quot;uniques&quot;:[&quot;[+1 Gold] &lt;with a garrison&gt;&quot;]</code> on a building - does almost the same thing as the <code>&quot;gold&quot;:1</code> attribute does, except it only applies when the city has a garrison. In this example, <code>[]</code> and <code>with a garrison</code> are the keys Unciv uses to look up two Uniques, an effect (of type <code>Stats</code>) and a condition (of type <code>ConditionalWhenGarrisoned</code>).</p><p>All Unique &quot;types&quot; that have an implementation in Unciv are automatically documented in <a href="./../uniques.html">uniques</a>. Note that file is entirely machine-generated from source code structures. Also kindly note the separate sections for <a href="./../uniques.html#conditional-uniques">conditionals</a> and <a href="./../uniques.html#triggercondition-uniques">trigger conditions</a>. Uniques that do not correspond to any of those entries (verbatim including upper/lower case!) are called &quot;untyped&quot;, will have no <em>direct</em> effect, and may result in the &quot;Ruleset Validator&quot; showing warnings (see the Options Tab &quot;Locate mod errors&quot;, it also runs when starting new games). A legitimate use of &quot;untyped&quot; Uniques is their use as markers that can be recognized elsewhere in <strong>filters</strong> (example: &quot;Aircraft&quot; in the vanilla rulesets used as <a href="./../Unique-parameters.html#baseunitfilter">Unit filter</a>). This use is recognized by the &quot;Ruleset Validator&quot; and not flagged as invalid - but a filtering Unique must also use <em>no placeholders or conditionals</em> to pass the test. If you get the &quot;not found in Unciv&#39;s unique types&quot; warning, but are sure you are using a correct filtering Unique, please look for exactly identical spelling in all places, including upper/lower case. Note: Currently some mods use untyped Uniques not for filtering purposes, but as purely informational tool. The team will try to think of an approach for that use that won&#39;t trigger validation warnings without reducing validation quality, but as of now, those are unavoidable.</p><h2 id="information-on-json-files-used-in-the-game" tabindex="-1">Information on JSON files used in the game <a class="header-anchor" href="#information-on-json-files-used-in-the-game" aria-label="Permalink to &quot;Information on JSON files used in the game&quot;">​</a></h2><p>Many parts of Unciv are moddable, and for each there is a separate json file. There is a json file for buildings, for units, for promotions units can have, for technologies, etc. The different new buildings or units you define can also have lots of different attributes, though not all are required. Below are tables documenting all the different attributes everything can have. Only the attributes which are noted to be &#39;required&#39; must be provided. All others have a default value that will be used when it is omitted.</p><p>The individual files are described on <a href="#table-of-contents">separate pages</a>.</p>`,28)])])}const p=t(n,[["render",o]]);export{f as __pageData,p as default};
